constructorMeta.signatureText:
constructor(
    /** 业务注册 ID，对应 BusinessRegistry 中的顶层注册项。 */
    businessRegistrationId: string, 
    /** 业务实例 ID，用于定位同一注册项下的具体实例。 */
    businessInstanceId: string)

constructor(businessRegistrationId: string, businessInstanceId: string, 
    /** 顶层实例 ID，参与生成后端 sessionId。 */
    instanceId: string, 
    /** 工具 runtime 内部实例 ID，当前通常与顶层实例 ID 一致。 */
    runtimeInstanceId: string)

constructor(
    /** 业务模块 ID，对应 registration.moduleId。 */
    moduleId: string, 
    /** 顶层模块实例 ID，例如 pageId 或业务草稿 ID。 */
    moduleInstanceId: string, 
    /** 顶层实例 ID，参与生成后端 sessionId。 */
    instanceId: string)

AiAgentAppendMessageOptions.declarationTypeText:
AiAgentRuntimeContext & Readonly<{
    /** 消息角色：user / assistant / system / tool */
    role: AiAgentMessageRole;
    /** 消息正文 */
    content: string;
    /** 消息来源标注（用于区分用户输入 / LLM 输出 / 工具返回值） */
    source?: AiAgentMessageSource;
    /** 附加元数据（如工具调用 ID、token 用量等） */
    metadata?: Record<string, unknown>;
}>

